def life(a,wrap=False):
 a=np.array(a);h,w=a.shape;out=np.zeros_like(a)
 for r in range(h):
  for c in range(w):
   n=0
   for dr in (-1,0,1):
    for dc in (-1,0,1):
     if dr==dc==0:continue
     rr,cc=r+dr,c+dc
     if wrap:rr%=h;cc%=w
     if 0<=rr<h and 0<=cc<w:n+=a[rr,cc]
   out[r,c]=int(n==3 or (a[r,c] and n==2))
 return out
